import pytest
from django.contrib.auth.models import Permission
from django.contrib.contenttypes.models import ContentType
from django.core.management import call_command
from django.db import connection

ORG_TABLES = (
    "organizations_organization",
    "organizations_orgrepository",
    "organizations_teammembership",
)

# The schema the removed organizations app created (from `sqlmigrate
# organizations 0001` on dev), so the drop runs against real tables and FKs.
OLD_SCHEMA = """
CREATE TABLE "organizations_organization" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(255) NOT NULL, "slug" varchar(255) NOT NULL UNIQUE,
    "description" text NOT NULL, "github_org_id" bigint NULL UNIQUE,
    "created_at" timestamp with time zone NOT NULL,
    "updated_at" timestamp with time zone NOT NULL,
    "owner_id" bigint NOT NULL REFERENCES "accounts_customuser" ("id")
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE "organizations_orgrepository" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "created_at" timestamp with time zone NOT NULL,
    "added_by_id" bigint NULL REFERENCES "accounts_customuser" ("id")
        DEFERRABLE INITIALLY DEFERRED,
    "organization_id" bigint NOT NULL REFERENCES "organizations_organization" ("id")
        DEFERRABLE INITIALLY DEFERRED,
    "repository_id" bigint NOT NULL REFERENCES "repositories_repository" ("id")
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE "organizations_teammembership" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "role" varchar(20) NOT NULL, "is_active" boolean NOT NULL,
    "created_at" timestamp with time zone NOT NULL,
    "updated_at" timestamp with time zone NOT NULL,
    "organization_id" bigint NOT NULL REFERENCES "organizations_organization" ("id")
        DEFERRABLE INITIALLY DEFERRED,
    "user_id" bigint NOT NULL REFERENCES "accounts_customuser" ("id")
        DEFERRABLE INITIALLY DEFERRED
);
"""


def _existing_org_tables() -> set[str]:
    with connection.cursor() as cursor:
        return set(ORG_TABLES) & set(connection.introspection.table_names(cursor))


def _recorded_org_migrations() -> int:
    with connection.cursor() as cursor:
        cursor.execute(
            "SELECT count(*) FROM django_migrations WHERE app = 'organizations'"
        )
        return cursor.fetchone()[0]


@pytest.mark.django_db
def test_fresh_database_has_no_organizations_tables():
    assert _existing_org_tables() == set()


@pytest.mark.django_db
def test_organizations_api_is_gone(auth_client):
    response = auth_client.get("/api/v1/organizations/")
    assert response.status_code == 404


@pytest.mark.django_db(transaction=True)
def test_migrating_forward_drops_old_organizations_tables(user):
    # Put the database back in the state dev left it in: organizations tables
    # with rows in them, the app's migration recorded, and its content types
    # and permissions still granted to a user.
    call_command("migrate", "core", "0001", verbosity=0)
    with connection.cursor() as cursor:
        cursor.execute(OLD_SCHEMA)
        cursor.execute(
            "INSERT INTO organizations_organization "
            "(name, slug, description, created_at, updated_at, owner_id) "
            "VALUES ('Org', 'org', '', now(), now(), %s) RETURNING id",
            [user.pk],
        )
        org_id = cursor.fetchone()[0]
        cursor.execute(
            "INSERT INTO organizations_teammembership "
            "(role, is_active, created_at, updated_at, organization_id, user_id) "
            "VALUES ('owner', true, now(), now(), %s, %s)",
            [org_id, user.pk],
        )
        cursor.execute(
            "INSERT INTO django_migrations (app, name, applied) "
            "VALUES ('organizations', '0001_initial', now())"
        )
    content_type = ContentType.objects.create(
        app_label="organizations", model="organization"
    )
    permission = Permission.objects.create(
        content_type=content_type, codename="view_organization", name="Can view"
    )
    user.user_permissions.add(permission)
    assert _existing_org_tables() == set(ORG_TABLES)

    call_command("migrate", "core", verbosity=0)

    assert _existing_org_tables() == set()
    assert _recorded_org_migrations() == 0
    assert not ContentType.objects.filter(app_label="organizations").exists()
    assert not Permission.objects.filter(pk=permission.pk).exists()
    assert not user.user_permissions.exists()
